using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;
using ShelfGuard.Application.Features.Erp.Posting;
using ShelfGuard.Application.Services;
using ShelfGuard.Domain.Entities;
using ShelfGuard.Domain.Entities.Erp;
using ShelfGuard.Infrastructure.Data;
using ShelfGuard.Infrastructure.Data.Repositories;
using ShelfGuard.Tests.Infrastructure;
using Xunit;
namespace ShelfGuard.Tests.Erp;
[Collection("ERP schema acceptance")]
public sealed class CatalogDesktopTests(ErpSchemaFixture fixture)
{
    private sealed class Access(WorkAccessScope s):IWorkAccessContext{public Task<WorkAccessScope?> GetAsync(CancellationToken ct=default)=>Task.FromResult<WorkAccessScope?>(s);}
    private DbContextOptions<AppDbContext> Options(params IInterceptor[] interceptors)=>new DbContextOptionsBuilder<AppDbContext>(TestPostgres.Options(Environment.GetEnvironmentVariable("SHELFGUARD_ERP_SCHEMA_TEST_DB")!)).AddInterceptors(interceptors).IgnoreManyServiceProvidersWarning().Options;
    private CatalogDesktopStore Store(WorkAccessScope s,params IInterceptor[] interceptors)=>new(Options(interceptors),new Access(s),TimeProvider.System);
    private static CatalogSave Item(string name="Desktop finished product",string? barcode=null)=>new(Guid.NewGuid(),"item",null,null,null,"Reviewed catalog product change",new(name,"kg","product",5,true,barcode==null?[]:[barcode]),null);
    private static CatalogSave Recipe(ProductionPostingPreviewPostgresTests.Scenario s)=>new(Guid.NewGuid(),"recipe",null,null,null,"Reviewed exact recipe composition",null,new("Desktop recipe",s.OutputId,2,null,true,[new(s.S.Item,4.5m)]));
    [ErpPostgresFact]public async Task Concurrent_item_retry_creates_one_card_and_source_audit_without_posting()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var c=Item();var rs=await Task.WhenAll(Store(s.Scope).SaveAsync(c,default),Store(s.Scope).SaveAsync(c,default));Assert.Single(rs,r=>r.Replayed);Assert.Equal(rs[0].DocumentId,rs[1].DocumentId);await using var db=fixture.Context();Assert.Single(await db.Items.Where(i=>i.Id==c.OperationId).ToListAsync());Assert.False(await db.DocumentPostings.AnyAsync(p=>p.DocumentId==rs[0].DocumentId));}
    [ErpPostgresFact]public async Task Concurrent_desktop_barcode_claims_cannot_assign_same_code_to_different_items()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var a=Item("First barcode product","W5I-EXACT");var b=Item("Second barcode product","W5I-EXACT");var errors=await Task.WhenAll(Record.ExceptionAsync(()=>Store(s.Scope).SaveAsync(a,default)),Record.ExceptionAsync(()=>Store(s.Scope).SaveAsync(b,default)));Assert.Single(errors,e=>e==null);Assert.Equal("catalog_barcode_conflict",Assert.IsType<CatalogConflict>(Assert.Single(errors,e=>e!=null)).Code);}
    [ErpPostgresFact]public async Task Item_edit_preserves_unexposed_prices_tax_and_existing_stock()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var before=await Store(s.Scope).ItemAsync(s.S.Item,default);var c=Item() with{Id=s.S.Item,ExpectedFingerprint=before.Fingerprint,Item=before.Data with{Name="Renamed catalog milk",Barcodes=["W5I-MILK"]}};await Store(s.Scope).SaveAsync(c,default);var now=await Store(s.Scope).ItemAsync(s.S.Item,default);Assert.Equal(before.CatalogPurchasePrice,now.CatalogPurchasePrice);Assert.Equal(before.VatRate,now.VatRate);Assert.Contains((await Store(s.Scope).ItemsAsync("W5I-MILK","all",1,default)).Items,i=>i.Id==s.S.Item);await using var db=fixture.Context();Assert.Equal(3.25m,(await db.ProductStocks.SingleAsync(b=>b.Id==s.S.Batch)).Quantity);}
    [ErpPostgresFact]public async Task Existing_item_unit_and_type_are_immutable()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var c=Item();await Store(s.Scope).SaveAsync(c,default);var source=await Store(s.Scope).ItemAsync(c.OperationId,default);foreach(var data in new[]{source.Data with{Unit="шт"},source.Data with{ItemType="service"}})Assert.Equal("catalog_item_identity_locked",(await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(c with{OperationId=Guid.NewGuid(),Id=source.Id,ExpectedFingerprint=source.Fingerprint,Item=data},default))).Code);}
    [ErpPostgresFact]public async Task Unused_catalog_item_can_be_archived_without_removing_audit_history()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var c=Item();await Store(s.Scope).SaveAsync(c,default);var source=await Store(s.Scope).ItemAsync(c.OperationId,default);await Store(s.Scope).SaveAsync(c with{OperationId=Guid.NewGuid(),Id=source.Id,ExpectedFingerprint=source.Fingerprint,Item=source.Data with{IsActive=false}},default);Assert.False((await Store(s.Scope).ItemAsync(source.Id,default)).Data.IsActive);}
    [ErpPostgresFact]public async Task Stock_or_recipe_reference_blocks_item_archive()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var i=await Store(s.Scope).ItemAsync(s.S.Item,default);Assert.Equal("catalog_item_in_use",(await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(Item() with{Id=i.Id,ExpectedFingerprint=i.Fingerprint,Item=i.Data with{IsActive=false}},default))).Code);}
    [ErpPostgresFact]public async Task Desktop_recipe_uses_catalog_units_and_runs_through_actual_ERP_production()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);await using(var db=fixture.Context()){(await db.Locations.SingleAsync(l=>l.Id==s.S.Location)).LocationType="production";await db.SaveChangesAsync();}var c=Recipe(s);await Store(s.Scope).SaveAsync(c,default);var recipe=await Store(s.Scope).RecipeAsync(c.OperationId,default);Assert.Equal("kg",recipe.Unit);Assert.Equal("l",Assert.Single(recipe.Lines).Unit);var access=new Access(s.Scope);var prod=new ProductionDesktopStore(Options(),access,s.Stock.Gate,new(true),TimeProvider.System);var order=await prod.CreateAsync(new(Guid.NewGuid(),s.S.Location,c.OperationId,2,null),default);var start=await prod.ReviewAsync(order.OrderId,"start",default);await prod.DecideAsync(order.OrderId,"start",new(Guid.NewGuid(),start.Order.Fingerprint,"Reviewed Desktop catalog production"),default);var reader=new ProductionPostingPreviewReader(Options(),s.Stock.Gate,new(true),TimeProvider.System);var plan=await reader.ReadAsync(s.Scope,order.OrderId,default);Assert.True(plan.CanPost);await new ProductionPostingStore(Options(),s.Stock.Gate,new(true),TimeProvider.System,reader).CompleteAsync(s.Scope,order.OrderId,new(Guid.NewGuid(),plan.Fingerprint,"Reviewed Desktop recipe actual output"),default);Assert.True((await Store(s.Scope).RecipeAsync(c.OperationId,default)).HasOrders);}
    [ErpPostgresFact]public async Task Used_recipe_cannot_be_rewritten_and_copy_preserves_old_order_recipe()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var source=await Store(s.Scope).RecipeAsync(s.RecipeId,default);var c=Recipe(s) with{Id=s.RecipeId,ExpectedFingerprint=source.Fingerprint,Recipe=source.Data with{Name="Changed historical recipe"}};Assert.Equal("catalog_recipe_sealed",(await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(c,default))).Code);var copy=c with{OperationId=Guid.NewGuid(),Id=null,BasedOnId=s.RecipeId};await Store(s.Scope).SaveAsync(copy,default);Assert.Equal(source.Data.Name,(await Store(s.Scope).RecipeAsync(s.RecipeId,default)).Data.Name);Assert.Equal(copy.Recipe!.Name,(await Store(s.Scope).RecipeAsync(copy.OperationId,default)).Data.Name);await using var db=fixture.Context();Assert.Equal(s.RecipeId,(await db.ProductionOrders.SingleAsync(o=>o.Id==s.OrderId)).RecipeId);}
    [ErpPostgresFact]public async Task Active_orders_block_recipe_archive_even_when_structure_unchanged()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var source=await Store(s.Scope).RecipeAsync(s.RecipeId,default);var c=Recipe(s) with{Id=s.RecipeId,ExpectedFingerprint=source.Fingerprint,Recipe=source.Data with{IsActive=false}};Assert.Equal("catalog_recipe_in_use",(await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(c,default))).Code);}
    [ErpPostgresFact]public async Task Unused_recipe_edit_replaces_BOM_atomically_and_stale_editor_cannot_overwrite()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var c=Recipe(s);await Store(s.Scope).SaveAsync(c,default);var old=await Store(s.Scope).RecipeAsync(c.OperationId,default);var edit=c with{OperationId=Guid.NewGuid(),Id=c.OperationId,ExpectedFingerprint=old.Fingerprint,Recipe=old.Data with{Ingredients=[new(s.S.Item,3.125m)]}};await Store(s.Scope).SaveAsync(edit,default);Assert.Equal(3.125m,Assert.Single((await Store(s.Scope).RecipeAsync(c.OperationId,default)).Lines).Quantity);await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(edit with{OperationId=Guid.NewGuid()},default));}
    [ErpPostgresFact]public async Task Copy_requires_current_parent_fingerprint_and_does_not_deactivate_parent()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var source=await Store(s.Scope).RecipeAsync(s.RecipeId,default);await using(var db=fixture.Context()){(await db.Items.SingleAsync(i=>i.Id==s.S.Item)).Name="Changed ingredient metadata";await db.SaveChangesAsync();}await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(Recipe(s) with{BasedOnId=s.RecipeId,ExpectedFingerprint=source.Fingerprint},default));Assert.True((await Store(s.Scope).RecipeAsync(s.RecipeId,default)).Data.IsActive);}
    [ErpPostgresFact]public async Task Inventory_catalog_works_without_production_module_but_recipe_access_does_not()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);await using(var db=fixture.Context()){(await db.Tenants.SingleAsync(t=>t.Id==s.S.Tenant)).UpdateModules(["inventory"]);await db.SaveChangesAsync();}var a=await Store(s.Scope).AccessAsync(default);Assert.True(a.CanManageItems);Assert.False(a.CanViewRecipes);await Store(s.Scope).SaveAsync(Item(),default);await Assert.ThrowsAsync<WorkAccessDeniedException>(()=>Store(s.Scope).RecipeAsync(s.RecipeId,default));}
    [ErpPostgresFact]public async Task Live_catalog_permission_revocation_blocks_writes_and_replays()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var c=Item();await Store(s.Scope).SaveAsync(c,default);await using(var db=fixture.Context()){(await db.Users.SingleAsync(u=>u.Id==s.S.Actor)).SetPermissions(new(){{"catalog.manage",false},{"production.manage",false}});await db.SaveChangesAsync();}Assert.False((await Store(s.Scope).AccessAsync(default)).CanManageItems);await Assert.ThrowsAsync<WorkAccessDeniedException>(()=>Store(s.Scope).SaveAsync(c,default));await Assert.ThrowsAsync<WorkAccessDeniedException>(()=>Store(s.Scope).SaveAsync(Recipe(s),default));}
    [ErpPostgresFact]public async Task Foreign_catalog_entity_and_ingredient_ids_are_rejected()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var other=await ProductionPostingPreviewPostgresTests.Seed(fixture);await Assert.ThrowsAsync<InventoryPostingNotFoundException>(()=>Store(s.Scope).ItemAsync(other.OutputId,default));await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(Recipe(s) with{Recipe=Recipe(s).Recipe! with{Ingredients=[new(other.S.Item,1)]}},default));}
    [ErpPostgresFact]public async Task Reviewed_reference_versions_reject_recipe_creation_after_ingredient_change()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var store=Store(s.Scope);var refs=await store.SelectionAsync([s.OutputId,s.S.Item],default);var c=Recipe(s) with{ItemFingerprints=refs.ToDictionary(i=>i.Id,i=>i.Fingerprint)};await using(var db=fixture.Context()){(await db.Items.SingleAsync(i=>i.Id==s.S.Item)).Name="New ingredient metadata";await db.SaveChangesAsync();}Assert.Equal("catalog_changed",(await Assert.ThrowsAsync<CatalogConflict>(()=>store.SaveAsync(c,default))).Code);await using(var db=fixture.Context())Assert.False(await db.Recipes.AnyAsync(r=>r.Id==c.OperationId));}
    [ErpPostgresFact]public async Task Recipe_archive_racing_new_order_cannot_leave_archived_recipe_with_active_order()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);await using(var db=fixture.Context()){(await db.Locations.SingleAsync(l=>l.Id==s.S.Location)).LocationType="production";await db.SaveChangesAsync();}var catalog=Store(s.Scope);var c=Recipe(s);await catalog.SaveAsync(c,default);var view=await catalog.RecipeAsync(c.OperationId,default);var archive=c with{OperationId=Guid.NewGuid(),Id=view.Id,ExpectedFingerprint=view.Fingerprint,Recipe=view.Data with{IsActive=false}};var prod=new ProductionDesktopStore(Options(),new Access(s.Scope),s.Stock.Gate,new(true),TimeProvider.System);var errors=await Task.WhenAll(Record.ExceptionAsync(()=>catalog.SaveAsync(archive,default)),Record.ExceptionAsync(()=>prod.CreateAsync(new(Guid.NewGuid(),s.S.Location,view.Id,2,null),default)));Assert.Single(errors,e=>e==null);var final=await catalog.RecipeAsync(view.Id,default);Assert.False(final.HasActiveOrders&&!final.Data.IsActive);}
    private sealed class FailAudit:SaveChangesInterceptor{public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData e,InterceptionResult<int> r,CancellationToken ct=default){if(e.Context!.ChangeTracker.Entries<BusinessDocument>().Any(x=>x.State==EntityState.Added&&x.Entity.SourceSystem.StartsWith("catalog.")))throw new InvalidOperationException("Synthetic catalog audit failure");return ValueTask.FromResult(r);}}
    [ErpPostgresFact]public async Task Audit_failure_rolls_back_new_item_and_idempotent_result_is_bound_to_intent()
    {var s=await ProductionPostingPreviewPostgresTests.Seed(fixture);var c=Item();await Assert.ThrowsAsync<InvalidOperationException>(()=>Store(s.Scope,new FailAudit()).SaveAsync(c,default));await using(var db=fixture.Context())Assert.False(await db.Items.AnyAsync(i=>i.Id==c.OperationId));await Store(s.Scope).SaveAsync(c,default);await Assert.ThrowsAsync<CatalogConflict>(()=>Store(s.Scope).SaveAsync(c with{Item=c.Item! with{Name="Other intent"}},default));}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(1.0001)][InlineData(10000000)]public void Recipe_quantity_requires_exact_positive_numeric10_3(decimal q)=>Assert.Throws<ArgumentException>(()=>CatalogRules.Quantity(q));
    [Fact]public void Catalog_rules_reject_duplicate_ingredients_and_normalize_barcodes()
    {var c=Item(barcode:"  W5I  ");Assert.Equal("W5I",Assert.Single(CatalogRules.Normalize(c).Item!.Barcodes));Assert.Throws<ArgumentException>(()=>CatalogRules.Normalize(c with{Item=c.Item! with{Barcodes=["A","A"]}}));var id=Guid.NewGuid();Assert.Throws<ArgumentException>(()=>CatalogRules.Normalize(new(Guid.NewGuid(),"recipe",null,null,null,"Reviewed recipe composition",null,new("Recipe",Guid.NewGuid(),1,null,true,[new(id,1),new(id,2)]))));}
}
